#include <bits/stdc++.h>
using namespace std;
int main(){
    string name;
    while (cin >> name) {
        double x1,y1,z1,x2,y2,z2;
        cin >> x1>>y1>>z1>>x2>>y2>>z2;
        int m; cin >> m;
        double dx=x2-x1, dy=y2-y1, dz=z2-z1;
        double totalLen = sqrt(dx*dx+dy*dy+dz*dz);
        double polluted = 0;
        for (int i=0;i<m;i++){
            double cx,cy,cz,r;
            cin >> cx>>cy>>cz>>r;
            double fx=x1-cx, fy=y1-cy, fz=z1-cz;
            double a = dx*dx+dy*dy+dz*dz;
            double b = 2*(fx*dx+fy*dy+fz*dz);
            double c = fx*fx+fy*fy+fz*fz - r*r;
            double disc = b*b-4*a*c;
            if (disc < 0) continue;
            double sq = sqrt(disc);
            double t1 = (-b - sq)/(2*a);
            double t2 = (-b + sq)/(2*a);
            double lo = max(0.0, t1), hi = min(1.0, t2);
            if (hi > lo) polluted += (hi-lo)*totalLen;
        }
        double pct = totalLen>0 ? polluted/totalLen*100.0 : 0.0;
        cout << name << "\n" << fixed << setprecision(2) << pct << "\n";
    }
}

